function solution(beginWord, endWord, wordList) {
  const words = new Set(wordList);
  if (!words.has(endWord)) return 0;
  let queue = [[beginWord, 1]];
  while (queue.length) {
    const next = [];
    for (const [w, d] of queue) {
      for (let i = 0; i < w.length; i++) {
        for (let c = 97; c <= 122; c++) {
          const cand = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
          if (cand === endWord) return d + 1;
          if (words.has(cand)) {
            words.delete(cand);
            next.push([cand, d + 1]);
          }
        }
      }
    }
    queue = next;
  }
  return 0;
}
